begin;
create or replace function public.confirm_financial_payment(p_tenant_id uuid,p_payment_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare payment public.financial_payments%rowtype;method public.financial_payment_methods%rowtype;cfg public.financial_payment_method_settlement_configs%rowtype;actor_id uuid:=public.current_tenant_user_id();begin
 select*into payment from public.financial_payments where id=p_payment_id and tenant_id=p_tenant_id for update;if not found then raise exception using errcode='P0002',message='FINANCIAL_PAYMENT_NOT_FOUND';end if;perform public.assert_financial_authorized(p_tenant_id,'financial.payment.confirm',null,null,payment.branch_id,payment.status='submitted');if payment.status<>'submitted'then raise exception using errcode='23514',message='FINANCIAL_PAYMENT_CONFIRM_STATE_INVALID';end if;select*into method from public.financial_payment_methods where id=payment.payment_method_id and tenant_id=p_tenant_id and is_active;if not found then raise exception using errcode='23514',message='PAYMENT_METHOD_INVALID_OR_INACTIVE';end if;if method.requires_reference and payment.reference_number is null then raise exception using errcode='23514',message='PAYMENT_METHOD_REFERENCE_REQUIRED';end if;
 if method.settlement_mode='clearing'then select*into cfg from public.financial_payment_method_settlement_configs where tenant_id=p_tenant_id and payment_method_id=method.id and is_active;if not found or(cfg.branch_id is not null and cfg.branch_id is distinct from payment.branch_id)then raise exception using errcode='42501',message='PAYMENT_CLEARING_CONFIGURATION_UNAVAILABLE';end if;perform public.assert_financial_authorized(p_tenant_id,'financial.payment.confirm',cfg.clearing_account_id,'reconcile',payment.branch_id,true);if payment.money_destination_id is not null then raise exception using errcode='23514',message='CLEARING_PAYMENT_MUST_NOT_HAVE_DIRECT_DESTINATION';end if;else if payment.money_destination_id is null or not exists(select 1 from public.list_allowed_payment_destinations(p_tenant_id,method.id,'financial.payment.confirm','confirm',payment.branch_id)a where a.destination_id=payment.money_destination_id)then raise exception using errcode='42501',message='PAYMENT_METHOD_REQUIRES_UNAVAILABLE_SETTLEMENT_OR_DESTINATION';end if;end if;
 update public.financial_payments set status='confirmed',confirmed_by=actor_id,confirmed_at=now()where id=payment.id;insert into public.financial_payment_events(tenant_id,payment_id,event_type,from_status,to_status,actor_user_id,metadata)values(p_tenant_id,payment.id,'confirmed','submitted','confirmed',actor_id,jsonb_build_object('settlement_mode',method.settlement_mode));return jsonb_build_object('payment_id',payment.id,'status','confirmed','settlement_mode',method.settlement_mode);end$$;
comment on function public.confirm_financial_payment(uuid,uuid)is'Confirms direct payments against a Money Destination and clearing-required payments against an authorized active method-specific clearing resource.';
commit;
